// Normalise un évènement Meta (WhatsApp / Messenger / Instagram) en un
// format commun. Renvoie null (aucun item) si ce n'est pas un message
// entrant exploitable (accusés de lecture, statuts de livraison, etc.).
const body = $input.first().json.body || {};
const results = [];

if (body.object === 'whatsapp_business_account') {
  for (const entry of body.entry || []) {
    for (const change of entry.changes || []) {
      for (const msg of change.value?.messages || []) {
        results.push({
          channel: 'whatsapp',
          customer_name: change.value?.contacts?.[0]?.profile?.name || null,
          customer_phone: msg.from || null,
          message: msg.text?.body || msg.button?.text || null,
          external_id: msg.id,
          order_details: null,
        });
      }
    }
  }
} else if (body.object === 'page') {
  for (const entry of body.entry || []) {
    for (const event of entry.messaging || []) {
      if (!event.message || event.message.is_echo) continue;
      results.push({
        channel: 'facebook',
        customer_name: null,
        customer_phone: event.sender?.id || null,
        message: event.message.text || null,
        external_id: event.message.mid,
        order_details: null,
      });
    }
  }
} else if (body.object === 'instagram') {
  for (const entry of body.entry || []) {
    for (const event of entry.messaging || []) {
      if (!event.message || event.message.is_echo) continue;
      results.push({
        channel: 'instagram',
        customer_name: null,
        customer_phone: event.sender?.id || null,
        message: event.message.text || null,
        external_id: event.message.mid,
        order_details: null,
      });
    }
  }
}

return results.map((r) => ({ json: { ...r, raw_payload: body } }));

// Adapte selon le format réel envoyé par TikTok (Leads Gen ou DM) une
// fois ton app développeur TikTok approuvée — la structure exacte dépend
// du produit TikTok utilisé (TikTok Lead Generation vs TikTok Shop).
const body = $input.first().json.body || {};

return [{
  json: {
    channel: 'tiktok',
    customer_name: body.lead_name || body.name || null,
    customer_phone: body.phone_number || body.phone || null,
    message: body.message || JSON.stringify(body).slice(0, 1000),
    external_id: body.lead_id || body.message_id || null,
    order_details: null,
    raw_payload: body,
  },
}];
